import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        T = int(next(iterator))
    except StopIteration:
        return

    for _ in range(T):
        try:
            s = next(iterator)
        except StopIteration:
            break

        n = len(s)
        char_indices = {}
        for idx, char in enumerate(s):
            if char not in char_indices:
                char_indices[char] = []
            char_indices[char].append(idx + 1)

        odd_count = 0
        odd_char = None
        for char, indices in char_indices.items():
            if len(indices) % 2 != 0:
                odd_count += 1
                odd_char = char

        if (n % 2 == 0 and odd_count > 0) or (n % 2 == 1 and odd_count != 1):
            print("-1")
            continue

        perm = [0] * n
        left = 0
        right = n - 1

        for char, indices in char_indices.items():
            if len(indices)%2 == 1:
                mid_idx = n // 2
                perm[mid_idx] = indices[0]
                continue

            count = len(indices)
            for i in range(count // 2):
                perm[left] = indices[i]
                perm[right] = indices[count - 1 - i]
                left += 1
                right -= 1

        print(" ".join(map(str, perm)))

if __name__ == "__main__":
    solve()
